# ============================================================
# CORRECTIONS QC — SOMEC_20251106
# Generated by interactive_mission_qc_console.R
# ============================================================

# # Charger les données avant d'appliquer les corrections :
# source("interactive_mission_qc_console.R")

# ============================================================
# FIXES
# ============================================================


# ── AVI090806 | CV_R4 | observations$R4 [2026-03-22 11:19] ──
# R4 fix: copy _rad into _par where _par is missing, then clear _rad
observations <- observations |>
  mutate(
    tra_par = if_else(mission == "AVI090806" &
      (is.na(tra_par) & is.na(dis_par)) &
      (!is.na(tra_rad) | !is.na(dis_rad)),
      tra_rad, tra_par),
    dis_par = if_else(mission == "AVI090806" &
      (is.na(tra_par) & is.na(dis_par)) &
      (!is.na(tra_rad) | !is.na(dis_rad)),
      dis_rad, dis_par),
    tra_rad = if_else(mission == "AVI090806" &
      !is.na(tra_par), NA_real_, tra_rad),
    dis_rad = if_else(mission == "AVI090806" &
      !is.na(dis_par), NA_real_, dis_rad)
  )

# ── GOR140228 | UNKNOWN_CATALOG | transects$site [2026-03-22 11:24] ──
transects <- transects |>
  mutate(
    site = case_when(
      site == "Début" ~ "début",
      site == "Fin" ~ "fin",
      TRUE ~ site
    )
  )

# ── GOR140228 | UNKNOWN_CATALOG | transects$act_plateforme [2026-03-22 11:25] ──
transects <- transects |>
  mutate(
    act_plateforme = case_when(
      act_plateforme == "EnDéplacement" ~ "Endéplacement",
      TRUE ~ act_plateforme
    )
  )

# ============================================================

# ── GOR140228 | OUTSIDE_MISSION_DATES | transects$heure [2026-03-22 11:25] ──
transects <- transects |>
  mutate(
    heure = if_else(
      mission == "GOR140228" &
      (heure < as.POSIXct("2014-02-28 00:00:00") |
       heure > as.POSIXct("2014-03-09 23:59:59")),
      as.POSIXct(paste(as.Date(date), format(heure, "%H:%M:%S")), tz="UTC"),
      heure
    )
  )


# ── GOR140228 | UNKNOWN_CATALOG_RECODE | observations$activite [2026-03-22 11:28] ──
observations <- observations |>
  mutate(
    activite = case_when(
      activite == "Vol" ~ "VOL",
      activite == "Eau" ~ "EAU",
      TRUE ~ activite
    )
  )

# CLOSING — save updated RDS + create new accdb (Windows only)
# ============================================================

saveRDS(missions,     file.path(.cache_dir, "missions.rds"))
saveRDS(transects,    file.path(.cache_dir, "transects.rds"))
saveRDS(observations, file.path(.cache_dir, "observations.rds"))
cat("\u2705 Updated RDS files saved.\n")

if (.Platform$OS.type == "windows") {
  .gestion_root <- dirname(.repo_root)
  .somec_root   <- dirname(.gestion_root)
  .accdb_src    <- file.path(.somec_root, "BaseDeDonnees", "SOMEC_20251106.accdb")
  .accdb_dst    <- file.path(.somec_root, "BaseDeDonnees", "SOMEC_20260322.accdb")
  file.copy(.accdb_src, .accdb_dst, overwrite = FALSE)
  con <- RODBC::odbcConnectAccess2007(.accdb_dst, believeNRows = FALSE)
  RODBC::sqlSave(con, missions,     tablename = "missions",     rownames = FALSE, append = FALSE)
  RODBC::sqlSave(con, transects,    tablename = "transects",    rownames = FALSE, append = FALSE)
  RODBC::sqlSave(con, observations, tablename = "observations", rownames = FALSE, append = FALSE)
  RODBC::odbcClose(con)
  cat("\u2705 New accdb created: SOMEC_20260322.accdb\n")
} else {
  cat("\u26a0\ufe0f  Run on Windows to create the new .accdb file.\n")
}
